            val svc = g.getService(SERVICE_UUID)
            if (svc == null) {
                pendingConnectCall = null; scanInFlight.set(false)
                call.reject("Servicio BLE Pay no encontrado en peer"); return
            }
            val intentChar = svc.getCharacteristic(CHAR_INTENT_UUID)
            if (intentChar == null) {
                pendingConnectCall = null; scanInFlight.set(false)
                call.reject("Characteristic INTENT no encontrada"); return
            }
            try {
                if (!g.readCharacteristic(intentChar)) {
                    pendingConnectCall = null; scanInFlight.set(false)
                    call.reject("readCharacteristic falló")
                }
            } catch (e: SecurityException) {
                pendingConnectCall = null; scanInFlight.set(false)
                call.reject("SecurityException en read: ${e.message}")
            }
