            if (characteristic.uuid == CHAR_INTENT_UUID) emitIntentUpdate(value)
        }

        // Legacy overload (<= API 32).
        @Suppress("DEPRECATION")
        override fun onCharacteristicChanged(
            g: BluetoothGatt,
            characteristic: BluetoothGattCharacteristic
