            if (characteristic.uuid != CHAR_ACK_UUID) return
            val call = pendingWriteAckCall ?: return
            pendingWriteAckCall = null
            if (status != BluetoothGatt.GATT_SUCCESS) {
                call.reject("write ACK status=$status"); return
            }
            val ret = JSObject(); ret.put("ok", true); call.resolve(ret)
            emitState("ack_written", "ok")
        }
    }
